<script>$(function(){var t=$('#expected-table'),branch=$('#expected-branch'),asOf=$('#expected-as-of'),from=$('#expected-from'),to=$('#expected-to'),x=$.fn.dataTable.render.text(),money=$.fn.dataTable.render.number(',','.',2);var dt=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.branch_scope=branch.val();d.as_of=asOf.val();d.from=from.val();d.to=to.val()}},order:[[6,'asc']],buttons:[window.erpExcelButton(t,function(){return{branch_scope:branch.val(),as_of:asOf.val(),from:from.val(),to:to.val()}})],columns:[{data:'type_label',name:'oi.ledger_type',render:function(v,type){return type==='display'?'<span class="badge '+(v==='รอรับเงิน'?'app-status-success':'app-status-warning')+'">'+x.display(v)+'</span>':v;}},{data:'document_number',name:'oi.document_number',render:x.display},{data:'party_label',name:'p.code',render:x.display},{data:'branch_code',name:'b.code',render:x.display},{data:'warehouse_code',name:'w.code',render:x.display},{data:'document_date_label',name:'oi.document_date',render:x.display},{data:'due_date_label',name:'oi.due_date',render:x.display},{data:'original_amount',name:'oi.original_amount',className:'text-end',render:money},{data:'allocated_amount',name:'allocated_amount',className:'text-end',render:money},{data:'outstanding_amount',name:'outstanding_amount',className:'text-end fw-semibold',render:money},{data:null,orderable:false,searchable:false,className:'text-end',render:function(v,type,row){return type==='display'?'<a class="btn btn-sm btn-app-soft" href="'+x.display(row.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-show" aria-hidden="true"></i></a>':'';}}]}));branch.add(asOf).add(from).add(to).on('change',function(){dt.ajax.reload()});$('#expected-reset').on('click',function(){branch.val('current');asOf.val('{{ today()->format('Y-m-d') }}');from.val('');to.val('');dt.ajax.reload()});});</script>
